package com.nse.dashboard.agent;import com.nse.dashboard.model.OptionData;import org.springframework.stereotype.Component;import java.util.*;@Component public class SentimentAgent { public String analyze(List<OptionData> data){ long totalPut=data.stream().mapToLong(OptionData::getPutOI).sum(); long totalCall=data.stream().mapToLong(OptionData::getCallOI).sum(); double pcr=(double)totalPut/totalCall; if(pcr>1.2)return"Bullish"; if(pcr<0.8)return"Bearish"; return"Sideways";}}